<style>
.print-workspace{--print-panel:#1a2029;--print-border:#3d4859;--print-text:#eef2f7;--print-muted:#b8c3d2;--print-input:#111720;max-width:1300px;margin:auto;color:var(--print-text);min-width:0}
.print-workspace .print-hero{padding:1.5rem;background:linear-gradient(115deg,#162b43,#202a37);border:1px solid #5f7e9e;border-radius:1rem;margin-bottom:1.25rem;display:flex;align-items:center;justify-content:space-between;gap:1.25rem;flex-wrap:wrap}
.print-workspace .eyebrow{font-size:.75rem;letter-spacing:.08em;text-transform:uppercase;color:#b4d1ef}.print-workspace h2{font-size:1.7rem;font-weight:650;line-height:1.25;margin:.5rem 0}.print-workspace .print-panel{background:var(--print-panel);border:1px solid var(--print-border);border-radius:1rem;padding:1.5rem;margin:1.25rem 0;min-width:0}.print-workspace h3{font-size:1.15rem;font-weight:600;margin-bottom:.4rem}.print-workspace .print-note,.print-cell-note{font-size:.875rem;color:var(--print-muted);line-height:1.6}.print-cell-note{display:block;margin-top:.4rem;overflow-wrap:anywhere}
.print-workspace .print-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1rem;margin-top:1.25rem}.print-workspace .print-field{display:block;min-width:0;font-size:.875rem}.print-workspace .print-field>span{display:block;font-weight:500;margin-bottom:.5rem}
.print-workspace input:not([type=checkbox]),.print-workspace select,.print-workspace textarea{width:100%;background:var(--print-input);color:var(--print-text);border:1px solid #69768a;border-radius:.6rem;padding:.75rem;font-size:.875rem;min-width:0}.print-workspace input:focus,.print-workspace select:focus,.print-workspace textarea:focus{outline:2px solid #8fc5fb;outline-offset:2px}.print-workspace b{color:#f7adb3}
.print-workspace .print-actions,.print-row-actions{display:flex;gap:.85rem;align-items:center;flex-wrap:wrap}.print-workspace .print-primary,.print-workspace .print-secondary{display:inline-flex;align-items:center;justify-content:center;min-height:2.75rem;padding:.7rem 1rem;border-radius:.65rem;font-size:.875rem;font-weight:600;cursor:pointer;text-decoration:none}.print-workspace .print-primary{background:#c52634;color:#fff;border:1px solid #e06a74}.print-workspace .print-secondary{background:#273649;color:#e2efff;border:1px solid #8197b1}
.print-workspace .print-item{border:1px solid var(--print-border);background:var(--print-input);border-radius:.8rem;padding:1.1rem;margin-top:1.1rem}.print-workspace .print-item-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:1rem;margin-top:1rem}.print-workspace .print-checks{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:1rem;margin-top:1.25rem}.print-workspace .print-checks label{font-size:.875rem;padding:1rem;background:var(--print-input);border:1px solid var(--print-border);border-radius:.7rem;display:flex;gap:.7rem;align-items:start}.print-workspace .print-checks input{margin-top:.2rem;accent-color:#79b8ef}
.print-workspace table{width:100%;border-collapse:collapse;font-size:.875rem}.print-workspace th,.print-workspace td{text-align:left;padding:1rem;border-bottom:1px solid var(--print-border);vertical-align:top}.print-workspace th{font-size:.8rem;color:#b8d2ed;font-weight:600;background:#243144}.print-table-wrap{overflow-x:auto;max-width:100%;border:1px solid var(--print-border);border-radius:.7rem;margin-top:1.2rem}.print-register{min-width:760px}.print-row-actions{min-width:9rem}.print-workspace .print-alert{background:#3b2730;color:#ffd4dc;padding:1rem;border:1px solid #c98495;border-radius:.75rem}.print-workspace .print-success{background:#163b31;color:#d0f6e7;padding:1rem;border:1px solid #71b99d;border-radius:.75rem}
.print-workspace .print-steps{width:100%;display:flex;gap:1rem;flex-wrap:wrap;margin-top:1rem;font-size:.875rem;color:#c3d5e7}.print-workspace .print-steps strong{color:#fff}.print-workspace .print-breadcrumb{color:#bbcbdc;font-size:.875rem;margin-bottom:1rem;display:flex;gap:.7rem;flex-wrap:wrap}.print-workspace button:disabled{opacity:.45;cursor:not-allowed}.print-workspace [x-cloak]{display:none!important}
.print-summary{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:1rem}.print-summary-item{display:block;min-width:0;background:var(--print-panel);border:1px solid var(--print-border);border-radius:.8rem;padding:1rem}.print-summary-item span{font-size:.875rem;color:var(--print-muted)}.print-summary-item strong{display:block;font-size:1.75rem;margin-top:.5rem}.print-filter{display:grid;grid-template-columns:2fr 1fr 1fr auto auto;gap:1rem;align-items:end;margin-top:1rem}.print-status{display:inline-block;padding:.35rem .6rem;border:1px solid #8295af;border-radius:.5rem;font-size:.8rem;white-space:normal}.print-status[data-state=pending]{border-color:#d9ac62;color:#ffe0ac}.print-status[data-state=approved]{border-color:#77c7aa;color:#c5f4e3}.print-status[data-state=needs_changes]{border-color:#de91a1;color:#ffd5df}.print-empty{padding:1.5rem 0;color:var(--print-muted)}.print-pagination{margin-top:1rem}.print-review-grid{display:grid;gap:1rem}.print-review-note{white-space:pre-wrap;overflow-wrap:anywhere}
html[data-theme=light] .print-workspace{--print-panel:#fff;--print-border:#c7d0dc;--print-text:#17243b;--print-muted:#4c5e73;--print-input:#f3f6fa}html[data-theme=light] .print-workspace th{background:#e8eef6;color:#243e5d}html[data-theme=light] .print-workspace .print-secondary{background:#e6eef8;color:#18314d}html[data-theme=light] .print-workspace .print-breadcrumb{color:#4c5e73}html[data-theme=light] .print-status{color:#253e5c}html[data-theme=light] .print-hero{color:#fff}html[data-theme=light] .print-hero .print-note{color:#c3d5e7}
@media(max-width:1000px){.print-workspace .print-item-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.print-workspace .print-grid,.print-workspace .print-checks,.print-summary{grid-template-columns:repeat(2,minmax(0,1fr))}.print-filter{grid-template-columns:1fr 1fr}}
@media(max-width:600px){.print-workspace .print-grid,.print-workspace .print-checks,.print-workspace .print-item-grid,.print-filter{grid-template-columns:1fr}.print-workspace .print-panel,.print-workspace .print-hero{padding:1rem}.print-workspace h2{font-size:1.4rem}.print-workspace .print-primary,.print-workspace .print-secondary{max-width:100%;overflow-wrap:anywhere}.print-workspace .print-actions>*{flex:1 1 auto}.print-summary{gap:.6rem}.print-summary-item{padding:.8rem}}
</style>
